{"filepath": "reproduce_notes.py", "content": "from rich.console import Console
from rich.traceback import Traceback

def test_notes():
    try:
        try:
            raise Exception("Original Error")
        except Exception as e:
            e.__notes__ = "Additional information\nSecond line of notes"
            raise e
    except Exception:
        console = Console(record=True)
        console.print_exception(show_traceback=True)
        print(console.export_text())

if __name__ == "__main__":
    test_notes()
